  landingFeatDesc:      { en: "Every design decision is grounded in the reality of a tehsil office.", hi: "हर डिज़ाइन निर्णय एक तहसील कार्यालय की वास्तविकता पर आधारित है।", mr: "प्रत्येक डिझाइन निर्णय तहसील कार्यालयाच्या वास्तवावर आधारित आहे." },
  landingConfLabel:     { en: "Officer trust", hi: "अधिकारी भरोसा", mr: "अधिकारी विश्वास" },
  landingConfTitle:     { en: "You always know how sure the AI is", hi: "आप हमेशा जानते हैं कि AI कितना आश्वस्त है", mr: "AI किती खात्रीशीर आहे हे तुम्हाला नेहमी कळते" },
  landingConfDesc1:     { en: "Every extracted field shows a confidence band — with an icon, a percentage and a colour. Roughly 8% of Indian men have colour-vision deficiency; BHUMI never relies on colour alone.", hi: "हर निकाले गए फ़ील्ड में एक कॉन्फिडेंस बैंड दिखाया जाता है — एक आइकन, प्रतिशत और रंग के साथ। लगभग 8% भारतीय पुरुषों में रंग-दृष्टि की कमी होती है; BHUMI कभी भी केवल रंग पर निर्भर नहीं करता।", mr: "प्रत्येक काढलेल्या फील्डमध्ये एक कॉन्फिडेंस बँड दाखवला जातो — चिन्ह, टक्केवारी आणि रंगासह. BHUMI कधीही फक्त रंगावर अवलंबून नसतो." },
  landingConfDesc2:     { en: "Low-confidence fields are automatically escalated to the review queue. Officers see the exact page region the AI read, side-by-side with the extracted value.", hi: "कम-कॉन्फिडेंस फ़ील्ड स्वचालित रूप से समीक्षा कतार में भेजे जाते हैं। अधिकारी AI द्वारा पढ़े गए सटीक पृष्ठ क्षेत्र को निकाले गए मूल्य के साथ देखते हैं।", mr: "कमी कॉन्फिडेंसचे फील्ड आपोआप पडताळणी रांगेत पाठवले जातात. अधिकाऱ्यांना AI ने वाचलेला अचूक पृष्ठ भाग दिसतो." },
  landingSeePipeline:   { en: "See the full pipeline", hi: "पूरी प्रक्रिया देखें", mr: "संपूर्ण प्रक्रिया पहा" },
  landingStakLabel:     { en: "Stakeholders", hi: "हितधारक", mr: "हितधारक" },
  landingStakTitle:     { en: "Who uses BHUMI", hi: "BHUMI का उपयोग कौन करता है", mr: "BHUMI कोण वापरतो" },
  landingCovLabel:      { en: "Coverage", hi: "कवरेज", mr: "कवरेज" },
  landingCovTitle:      { en: "Active across {0}+ states", hi: "{0}+ राज्यों में सक्रिय", mr: "{0}+ राज्यांमध्ये सक्रिय" },
  landingCovDesc:       { en: "Pilot deployments live · National rollout under DILRMP Phase III", hi: "पायलट तैनाती जारी · DILRMP चरण III के तहत राष्ट्रीय विस्तार", mr: "पायलट तैनाती सुरू · DILRMP टप्पा III अंतर्गत राष्ट्रीय विस्तार" },
  landingCovMore:       { en: "+ 16 more rolling out", hi: "+ 16 और विस्तारित हो रहे हैं", mr: "+ 16 आणखी विस्तारत आहेत" },
  landingCompLabel:     { en: "Why BHUMI", hi: "BHUMI क्यों", mr: "BHUMI का" },
  landingCompTitle:     { en: "How it compares?", hi: "यह कैसे तुलना करता है?", mr: "हे कसे तुलना करते?" },
  landingCompDesc:      { en: "Side-by-side: BHUMI vs the traditional manual process for land record management.", hi: "एक नज़र में: भूमि बनाम पारंपरिक मैनुअल प्रक्रिया।", mr: "एका दृष्टिक्षेपात: BHUMI विरुद्ध पारंपरिक प्रक्रिया." },
  landingCompMetric:    { en: "Metric", hi: "मापदंड", mr: "मापदंड" },
