  sitemapSec4:        { en: "Platform (sign-in required)", hi: "प्लेटफ़ॉर्म (लॉगिन आवश्यक)", mr: "प्लॅटफॉर्म (साइन-इन आवश्यक)" },

  // ─── Developers page ──────────────────────────────────────────────────────
  devLabel:           { en: "Developers",          hi: "डेवलपर्स",              mr: "डेव्हलपर्स" },
  devTitle:           { en: "Developer API",       hi: "डेवलपर API",            mr: "डेव्हलपर API" },
  devSubtitle:        { en: "Integrate BHUMI land-records data into your state systems, mobile apps, and GIS platforms. The REST API is available to authorised government entities only.", hi: "BHUMI भूमि-रिकॉर्ड डेटा को अपने राज्य सिस्टम, मोबाइल ऐप और GIS प्लेटफ़ॉर्म में एकीकृत करें। REST API केवल अधिकृत सरकारी संस्थाओं के लिए उपलब्ध है।", mr: "BHUMI जमीन-अभिलेख डेटा तुमच्या राज्य प्रणाली, मोबाइल अॅप्स आणि GIS प्लॅटफॉर्ममध्ये समाकलित करा." },
  devCardKeys:        { en: "API keys",            hi: "API कुंजियाँ",           mr: "API कळा" },
  devCardKeysBody:    { en: "Each integration is issued a scoped API key via your administrator account. Keys rotate every 90 days.", hi: "प्रत्येक एकीकरण को प्रशासक खाते के माध्यम से एक स्कोप्ड API कुंजी जारी की जाती है। कुंजियाँ हर 90 दिनों में बदलती हैं।", mr: "प्रत्येक एकीकरणाला प्रशासक खात्याद्वारे स्कोप केलेली API की जारी केली जाते. की दर 90 दिवसांनी बदलते." },
  devCardSec:         { en: "Security",            hi: "सुरक्षा",               mr: "सुरक्षा" },
  devCardSecBody:     { en: "All API calls require Bearer token authentication over TLS 1.3. Rate limits: 1,000 req/min per key.", hi: "सभी API कॉल में TLS 1.3 पर Bearer टोकन प्रमाणीकरण आवश्यक है। दर सीमा: प्रति कुंजी 1,000 अनुरोध/मिनट।", mr: "सर्व API कॉल्ससाठी TLS 1.3 वर Bearer टोकन प्रमाणीकरण आवश्यक आहे." },
  devCardRate:        { en: "Rate limits",         hi: "दर सीमाएँ",             mr: "दर मर्यादा" },
  devCardRateBody:    { en: "Standard tier: 1,000 requests/minute. Bulk export endpoints have separate quotas; contact us for higher limits.", hi: "मानक स्तर: 1,000 अनुरोध/मिनट। बल्क एक्सपोर्ट एंडपॉइंट की अलग कोटा है।", mr: "मानक स्तर: 1,000 विनंत्या/मिनिट. बल्क एक्सपोर्ट एंडपॉइंटसाठी वेगळे कोटा आहेत." },
  devCardSDK:         { en: "SDKs",               hi: "SDKs",                  mr: "SDKs" },
  devCardSDKBody:     { en: "Official Python and Node.js SDKs are under development. OpenAPI 3.1 spec available on request.", hi: "आधिकारिक Python और Node.js SDK विकास के अधीन हैं। OpenAPI 3.1 स्पेक अनुरोध पर उपलब्ध है।", mr: "अधिकृत Python आणि Node.js SDK विकासाधीन आहेत. OpenAPI 3.1 स्पेक विनंतीवर उपलब्ध." },
  devEndpoints:       { en: "Available endpoints", hi: "उपलब्ध एंडपॉइंट",       mr: "उपलब्ध एंडपॉइंट" },
  devBaseURL:         { en: "Base URL:",           hi: "बेस URL:",              mr: "बेस URL:" },
  devColMethod:       { en: "Method",              hi: "विधि",                  mr: "पद्धत" },
  devColEndpoint:     { en: "Endpoint",            hi: "एंडपॉइंट",              mr: "एंडपॉइंट" },
  devColDesc:         { en: "Description",         hi: "विवरण",                 mr: "वर्णन" },
  devRequestTitle:    { en: "Request API access",  hi: "API एक्सेस अनुरोध करें", mr: "API ऍक्सेस विनंती करा" },
  devRequestBody:     { en: "API access is restricted to authorised government entities. Submit your request via the Contact page and our integration team will respond within five working days.", hi: "API एक्सेस केवल अधिकृत सरकारी संस्थाओं तक सीमित है। Contact पेज के माध्यम से अनुरोध सबमिट करें।", mr: "API ऍक्सेस केवळ अधिकृत सरकारी संस्थांपुरते मर्यादित आहे. Contact पृष्ठाद्वारे विनंती सबमिट करा." },
  devRequestBtn:      { en: "Request access",      hi: "एक्सेस अनुरोध करें",    mr: "ऍक्सेस विनंती करा" },

