/** Translate a key to the current locale, falling back to English then the key itself. */
export function t(key: string, locale: Locale, replacements?: string[]): string {
  const template = STRINGS[key]?.[locale] ?? STRINGS[key]?.["en"] ?? key;
  if (!replacements?.length) return template;
  return replacements.reduce((s, r, i) => s.replace(`{${i}}`, r), template);
}
